// ConditionGenerator.js

export const generateCondition = (category, keyword = '') => {
  // 카테고리별 기초 데이터 소스
  const baseData = {
    line: ['Line-A', 'Line-B', 'Line-C', 'Line-D'],
    process: ['Photo', 'Etch', 'Clean', 'Diff', 'CMP', 'Ion-Imp'],
    partid: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    product: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    equip: ['EQP-01', 'EQP-02', 'EQP-03', 'EQP-04', 'EQP-05'],
    lottype: ['Production', 'Test', 'Engineer', 'Rework'],
    step: ['HS010092-01', 'HS010092-02', 'HS010093-01', 'HS010094-01'],
    lot: ['LOT-ID-001', 'LOT-ID-002', 'LOT-ID-003', 'LOT-ID-004', 'LOT-ID-005'],
    wafer: ['W01', 'W02', 'W03', 'W04', 'W05', 'W06', 'W07', 'W08', 'W09', 'W10'],
    item: [
      'Thickness',
      'Critical Dimension',
      'Overlay',
      'Defect Count',
      'Temperature',
      'Pressure',
      'Flow Rate',
      'Humidity',
    ],
  };

  const list = [];
  let source = baseData[category] || ['Unknown'];
  if (category === 'y1item' || category === 'y2item') {
    source = baseData['item'];
  }

  // 20개 이상의 데이터를 생성하기 위한 루프
  for (let i = 1; i <= 20; i++) {
    const baseValue = source[i % source.length];
    let item = `${baseValue}_${String(i).padStart(3, '0')}`;
    if (category === 'lot') item = `${baseValue}.W${String(i).padStart(2, '0')}`;

    // 키워드가 있을 경우 필터링 로직 (소문자 기준)
    if (!keyword) {
      list.push(item);
    } else {
      for (const filter of keyword) {
        if (item.toLowerCase().includes(filter)) {
          list.push(item);
          break;
        }
      }
    }
  }

  return list;
};
