import { useState } from 'react';
import './App.css';
import HeaderMenu from './components/Header-Menu';
import LayoutMonitoring from './components/monitoring/Layout-Monitoring';
import LayoutMap from './components/map/Layout-Map';
import PortfolioLoader from './components/PortfolioLoader';
import AboutProject from './components/AboutProject';

function AppDeviceSolution() {
  const [menuType, setMenuType] = useState('Monitoring');
  const [dataType, setDataType] = useState('Gen');
  const [userId, setUserId] = useState('admin_user');

  return (
    <div>
      <HeaderMenu className="Top-header" onMenuType={setMenuType} onDataType={setDataType} />
      {menuType === 'Monitoring' && <LayoutMonitoring userId={userId} />}
      {menuType === 'Map' && <LayoutMap dataType={dataType} userId={userId} />}
      {menuType === 'About' && <AboutProject />}
    </div>
  );
}

export default AppDeviceSolution;
